const frame = page.frame({ url: /tools\/canvas-rce/ });
const info = await frame.evaluate(() => {
  const content = document.querySelector('.content');
  const results = [];
  for (const sheet of document.styleSheets) {
    let rules;
    try { rules = sheet.cssRules; } catch { continue; }
    for (const rule of rules) {
      if (rule.selectorText && rule.selectorText.includes('.content') && rule.style && rule.style.display) {
        results.push({ href: sheet.href, selector: rule.selectorText, cssText: rule.cssText.slice(0,200) });
      }
    }
  }
  return { display: getComputedStyle(content).display, flexDirection: getComputedStyle(content).flexDirection, matches: results };
});
return info;
